/* Bundle exporter — assembles a downloadable .zip targeting either a C
 * app or a JS app. Pure: all environment bits (JSZip, the loaded
 * exporters, a PNG renderer, the lib source files) are injected by the
 * caller so this module is testable and path-agnostic.
 *
 *   const { blob, filename } = await exportBundle(state, {
 *     target: "c" | "js", exporters, JSZip, renderIconPng, libFiles });
 */

function ns(state) {
  return (state.app.namespace || "app").replace(/[^a-zA-Z0-9_]/g, "_") || "app";
}

function cReadme(name) {
  return `# ${name} — C app bundle

Generated by Flipper GUI Studio.

## Files

- \`${name}_scene.h\` / \`${name}_scene.c\` — scene draw + input callbacks.
- \`${name}_icons.h\` — XBM icon byte arrays (\`canvas_draw_xbm\`).
- \`snippets/${name}_<screen>_draw.c\` — a standalone draw snippet per
  screen, if you'd rather copy individual draw bodies.

## Use

Drop the files into your app, \`#include "${name}_icons.h"\`, and call the
scene's draw callback from your view's draw handler. Icons are 1-bit XBM:

\`\`\`c
canvas_draw_xbm(canvas, x, y, ICON_W, ICON_H, I_my_icon_16x16);
\`\`\`
`;
}

function jsReadme(name) {
  return `# ${name} — JS app bundle

Generated by Flipper GUI Studio. Renders the 128×64 Flipper UI to an HTML
canvas, pixel-identical to the editor.

## Files

- \`index.html\` — open it (over a static server) to preview every screen.
- \`spec.json\` — the full design (screens, widgets, icons).
- \`render.js\` — \`renderScreen(ctx, screen, icons)\` + \`renderAll(spec, mount)\`.
- \`lib/\` — the shared 1-bit renderer + fonts (do not edit).
- \`icons.js\` — \`name → { w, h, bits, dataURL }\` for using icons directly.
- \`icons/png/\` — each icon as a transparent PNG (1× and @4×).

## Use

\`\`\`js
import { renderAll } from "./render.js";
const spec = await fetch("./spec.json").then((r) => r.json());
renderAll(spec, document.body);
\`\`\`

Must be served over HTTP (ES modules + fetch don't work from \`file://\`):

\`\`\`sh
python3 -m http.server
\`\`\`
`;
}

const RENDER_JS = `/* Standalone screen renderer for the exported design. Shares the exact
   1-bit drawing code used by Flipper GUI Studio's editor. */

import { drawScene } from "./lib/draw-scene.js";
import { preloadFonts } from "./lib/font-render.js";

const PAPER = "#f0f0d0"; // Flipper LCD background

export function renderScreen(ctx, screen, icons) {
  ctx.fillStyle = PAPER;
  ctx.fillRect(0, 0, 128, 64);
  drawScene(ctx, screen.widgets || [], icons || []);
}

export async function renderAll(spec, mount) {
  await preloadFonts();
  for (const screen of spec.screens || []) {
    const wrap = document.createElement("div");
    wrap.className = "screen";
    const h = document.createElement("h2");
    h.textContent = screen.name || screen.id;
    const cv = document.createElement("canvas");
    cv.width = 128;
    cv.height = 64;
    renderScreen(cv.getContext("2d"), screen, spec.icons || []);
    wrap.appendChild(h);
    wrap.appendChild(cv);
    mount.appendChild(wrap);
  }
}
`;

function demoHtml(name) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>${name} — Flipper GUI preview</title>
<style>
  body { margin: 0; padding: 24px; background: #1b1d22; color: #e8e8e8; font-family: system-ui, sans-serif; }
  h1 { font: 600 16px ui-monospace, monospace; }
  .screen { margin-bottom: 24px; }
  .screen h2 { font: 12px ui-monospace, monospace; color: #9aa; margin: 0 0 6px; }
  canvas { image-rendering: pixelated; width: 512px; height: 256px; background: #f0f0d0; display: block; border: 1px solid #333; }
</style>
</head>
<body>
<h1>${name}</h1>
<div id="mount"></div>
<script type="module">
  import { renderAll } from "./render.js";
  const spec = await fetch("./spec.json").then((r) => r.json());
  renderAll(spec, document.getElementById("mount"));
</script>
</body>
</html>
`;
}

export async function exportBundle(state, { target, exporters, JSZip, renderIconPng, libFiles }) {
  const zip = new JSZip();
  const name = ns(state);

  if (target === "c") {
    const root = zip.folder(`${name}_c_app`);
    for (const f of exporters.scene()) root.file(f.filename, f.text); // [h, c]
    const icons = exporters.xbm();
    root.file(icons.filename, icons.text);
    const snippets = root.folder("snippets");
    for (const sc of state.screens) {
      const snip = exporters.snippetFor(sc.id);
      snippets.file(snip.filename, snip.text);
    }
    root.file("README.md", cReadme(name));
    return { blob: await zip.generateAsync({ type: "blob" }), filename: `${name}_c_app.zip` };
  }

  // JS target.
  const root = zip.folder(`${name}_js_app`);
  root.file("spec.json", exporters.json().text);
  root.file("render.js", RENDER_JS);
  root.file("index.html", demoHtml(name));
  root.file("README.md", jsReadme(name));

  for (const [path, text] of Object.entries(libFiles)) {
    root.file(`lib/${path}`, text);
  }

  const png = root.folder("icons/png");
  const iconEntries = [];
  for (const ic of state.icons) {
    const one = await renderIconPng(ic, 1);
    const four = await renderIconPng(ic, 4);
    png.file(`${ic.name}.png`, one.blob);
    png.file(`${ic.name}@4x.png`, four.blob);
    iconEntries.push(
      `  ${JSON.stringify(ic.name)}: { w: ${ic.w}, h: ${ic.h}, ` +
      `bits: ${JSON.stringify(ic.bits)}, dataURL: ${JSON.stringify(one.dataURL)} }`
    );
  }
  root.file("icons.js",
    `/* Icon assets for ${name}. bits = base64 XBM (LSB-first); dataURL = PNG. */\n` +
    `export default {\n${iconEntries.join(",\n")}\n};\n`);

  return { blob: await zip.generateAsync({ type: "blob" }), filename: `${name}_js_app.zip` };
}
